=== FILE: rr_arbiter.v ===
// rr_arbiter.v
// Round-robin arbiter for N requesters (default 4).
// Interface:         interface_spec.md (ports, reset, behavior, fairness)
// Microarchitecture: microarchitecture.md
//   sec 1: the only state is ptr, $clog2(N) bits, reset to 0
//   sec 2: wrapping priority search from ptr, wrap by comparing with LAST
//   sec 3: on a grant ptr <= winner + 1 (wrapping); no request, ptr holds
//   sec 4: synchronous active-low reset; grant is not gated by reset
`default_nettype none

module rr_arbiter #(
  parameter integer N = 4
) (
  input  wire         clk,
  input  wire         rst_n,
  input  wire [N-1:0] req,
  output reg  [N-1:0] grant
);

  localparam integer  PW    = (N > 1) ? $clog2(N) : 1;
  localparam integer  LASTI = N - 1;
  localparam integer  ONEI  = 1;
  localparam [PW-1:0] LAST  = LASTI[PW-1:0];
  localparam [PW-1:0] ONE   = ONEI[PW-1:0];

  reg [PW-1:0] ptr;       // highest-priority requester this cycle
  reg [PW-1:0] ptr_next;
  reg [PW-1:0] winner;    // index of the granted requester
  reg [PW-1:0] idx;       // search position
  reg          found;
  integer      i;

  // Grant logic and next pointer: pure combinational, every output defaulted.
  always @* begin
    grant  = {N{1'b0}};
    winner = {PW{1'b0}};
    found  = 1'b0;
    idx    = ptr;
    // Walk from ptr upwards, wrapping from LAST (N-1) to 0.
    for (i = 0; i < N; i = i + 1) begin
      if (!found && req[idx]) begin
        found  = 1'b1;
        winner = idx;
      end
      if (idx == LAST) begin
        idx = {PW{1'b0}};
      end else begin
        idx = idx + ONE;
      end
    end
    for (i = 0; i < N; i = i + 1) begin
      grant[i] = found && (winner == i[PW-1:0]);
    end
    // Pointer moves one past the winner only when something was granted.
    if (!found) begin
      ptr_next = ptr;
    end else if (winner == LAST) begin
      ptr_next = {PW{1'b0}};
    end else begin
      ptr_next = winner + ONE;
    end
  end

  // Pointer register: synchronous active-low reset to 0.
  always @(posedge clk) begin
    if (!rst_n) begin
      ptr <= {PW{1'b0}};
    end else begin
      ptr <= ptr_next;
    end
  end

`ifdef FORMAL
  // Design-intent properties (microarchitecture.md sec 5).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge clk) f_past_valid <= 1'b1;

  // Reset is active on the first cycle.
  always @(*) begin
    if (!f_past_valid) assume (!rst_n);
  end

  // Grant is one-hot or zero, only to a requester, and work conserving.
  always @(*) begin
    assert ((grant & (grant - {{(N-1){1'b0}}, 1'b1})) == {N{1'b0}});
    assert ((grant & ~req) == {N{1'b0}});
    assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
    if (f_past_valid) assert (ptr <= LAST);
  end

  // Pointer: 0 after reset, one past the winner after a grant, else holds.
  always @(posedge clk) begin
    if (f_past_valid) begin
      if (!$past(rst_n)) begin
        assert (ptr == {PW{1'b0}});
      end else if ($past(found)) begin
        if ($past(winner) == LAST) assert (ptr == {PW{1'b0}});
        else                       assert (ptr == $past(winner) + ONE);
      end else begin
        assert (ptr == $past(ptr));
      end
    end
  end

  // Distance from the pointer to the winner.
  wire [31:0] f_wdist = (winner >= ptr) ? (winner - ptr) : (winner + N - ptr);

  genvar g;
  generate
    for (g = 0; g < N; g = g + 1) begin : g_formal
      wire [31:0] f_dist = (g >= ptr) ? (g - ptr) : (g + N - ptr);
      reg  [PW:0] f_wait;
      initial f_wait = {(PW+1){1'b0}};

      // Consecutive cycles requester g asked out of reset and was not granted.
      always @(posedge clk) begin
        if (!rst_n || !req[g] || grant[g]) f_wait <= {(PW+1){1'b0}};
        else                               f_wait <= f_wait + 1'b1;
      end

      always @(*) begin
        // Round-robin order: no requester between the pointer and the winner.
        if (f_past_valid && req[g]) assert (f_wdist <= f_dist);
        if (f_past_valid) begin
          // Fairness bound and its induction invariant.
          assert (f_wait <= LAST);
          if (f_wait != {(PW+1){1'b0}}) assert (f_dist + f_wait <= LASTI);
        end
        cover (f_past_valid && rst_n && grant[g]);
        cover (f_past_valid && f_wait == LAST);
      end
    end
  endgenerate

  always @(posedge clk) begin
    if (f_past_valid) begin
      cover (rst_n && (req == {N{1'b1}}));
      cover ($past(rst_n) && $past(found) && ($past(winner) == LAST) && (ptr == {PW{1'b0}}));
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb.v
// Self-checking testbench for rr_arbiter: two lanes, N = 4 and N = 5.
// Each lane checks grant every cycle against a reference pointer model,
// checks that no held request waits N cycles, and fails the run if a
// coverage goal of interface_spec.md sec 6 was not reached.
// Check codes reported by $error:
//   1 grant differs from the reference model
//   2 grant not one-hot or zero
//   3 grant to a requester that is not requesting
//   4 request present but no grant (not work conserving)
//   5 held request waited more than N-1 cycles
//   6 strict rotation 0..N-1 after reset violated
//   20 no-request cycle not covered        21 everyone-requesting not covered
//   22 longest fair wait (N-1) not covered 23 held among changing others not covered
//   24 reset during traffic not covered    25 pointer wrap not covered
//   26 max observed wait above N-1         30+r requester r alone not covered

module rr_arbiter_tb_lane #(
  parameter integer N    = 4,
  parameter [31:0]  SEED = 32'h0000_0001
) (
  input  wire        clk,
  output reg         done,
  output reg  [31:0] passed,
  output reg  [31:0] failed
);
  localparam [N-1:0] ONE_N = {{(N-1){1'b0}}, 1'b1};
  localparam [N-1:0] ALL_N = {N{1'b1}};
  localparam [N-1:0] NONE  = {N{1'b0}};

  reg          rst_n;
  reg  [N-1:0] req;
  wire [N-1:0] grant;

  rr_arbiter #(.N(N)) u_dut (
    .clk   (clk),
    .rst_n (rst_n),
    .req   (req),
    .grant (grant)
  );

  // Reference model and bookkeeping
  integer     ref_ptr;
  reg         model_valid;
  integer     exp_win;
  reg [N-1:0] exp_grant;
  integer     wait_cnt [0:N-1];
  integer     max_wait_seen;
  reg [N-1:0] prev_req;
  reg         prev_valid;
  reg         seen_run;
  reg [31:0]  rng;
  integer     cov_none, cov_all, cov_maxwait, cov_held, cov_reset_traffic, cov_wrap;
  integer     cov_alone [0:N-1];
  integer     r, k, j, c;

  function bit_at(input [N-1:0] v, input integer pos);
    begin
      bit_at = |(v & (ONE_N << pos));
    end
  endfunction

  function [31:0] xorshift(input [31:0] x);
    reg [31:0] y;
    begin
      y = x ^ (x << 13);
      y = y ^ (y >> 17);
      y = y ^ (y << 5);
      xorshift = y;
    end
  endfunction

  task tally(input ok, input integer code);
    begin
      if (ok) begin
        passed = passed + 32'd1;
      end else begin
        failed = failed + 32'd1;
        $error("rr_arbiter_tb N=%0d t=%0t check %0d failed: rst_n=%b req=%b grant=%b exp=%b ref_ptr=%0d",
               N, $time, code, rst_n, req, grant, exp_grant, ref_ptr);
      end
    end
  endtask

  // Expected grant: first requester at or after ref_ptr, wrapping modulo N.
  task compute_expected;
    begin
      exp_grant = NONE;
      exp_win   = -1;
      for (k = 0; k < N; k = k + 1) begin
        j = (ref_ptr + k) % N;
        if (exp_win < 0 && bit_at(req, j)) exp_win = j;
      end
      if (exp_win >= 0) exp_grant = ONE_N << exp_win;
    end
  endtask

  // One clock cycle: inputs were set after a falling edge; check before the
  // rising edge, update the model at the rising edge, return at the falling edge.
  task do_cycle;
    begin
      #1;
      if (model_valid) begin
        compute_expected;
        tally(grant === exp_grant, 1);
        tally((grant & (grant - ONE_N)) === NONE, 2);
        tally((grant & ~req) === NONE, 3);
        tally((req === NONE) || (grant !== NONE), 4);
        for (r = 0; r < N; r = r + 1) begin
          if (!rst_n || !bit_at(req, r) || bit_at(grant, r)) wait_cnt[r] = 0;
          else wait_cnt[r] = wait_cnt[r] + 1;
          if (wait_cnt[r] > max_wait_seen) max_wait_seen = wait_cnt[r];
          if (wait_cnt[r] == N - 1) cov_maxwait = cov_maxwait + 1;
          if (rst_n && bit_at(req, r)) tally(wait_cnt[r] <= N - 1, 5);
          if (rst_n && prev_valid && bit_at(req, r) && bit_at(prev_req, r) &&
              ((req & ~(ONE_N << r)) !== (prev_req & ~(ONE_N << r))))
            cov_held = cov_held + 1;
          if (rst_n && (req === (ONE_N << r))) cov_alone[r] = cov_alone[r] + 1;
        end
        if (rst_n && (req === NONE))  cov_none = cov_none + 1;
        if (rst_n && (req === ALL_N)) cov_all  = cov_all + 1;
        if (rst_n && (exp_win == N - 1)) cov_wrap = cov_wrap + 1;
        if (!rst_n && seen_run && (req !== NONE) && (ref_ptr != 0))
          cov_reset_traffic = cov_reset_traffic + 1;
        if (rst_n) seen_run = 1'b1;
        prev_req   = req;
        prev_valid = rst_n;
      end
      @(posedge clk);
      if (!rst_n) begin
        ref_ptr     = 0;
        model_valid = 1'b1;
      end else if (model_valid && (exp_win >= 0)) begin
        if (exp_win == N - 1) ref_ptr = 0;
        else                  ref_ptr = exp_win + 1;
      end
      @(negedge clk);
    end
  endtask

  task apply(input [N-1:0] v, input integer cycles);
    integer n;
    begin
      for (n = 0; n < cycles; n = n + 1) begin
        req = v;
        do_cycle;
      end
    end
  endtask

  // Everyone requesting right after reset: grants must be 0, 1, ..., N-1, 0, ...
  task rotation(input integer rounds);
    integer n;
    begin
      for (n = 0; n < rounds * N; n = n + 1) begin
        req = ALL_N;
        #1;
        tally(grant === (ONE_N << (n % N)), 6);
        do_cycle;
      end
    end
  endtask

  // One requester held while the others change randomly.
  task held(input integer target, input integer cycles);
    integer n;
    begin
      for (n = 0; n < cycles; n = n + 1) begin
        rng = xorshift(rng);
        req = rng[N-1:0] | (ONE_N << target);
        do_cycle;
      end
    end
  endtask

  // Random subsets, single requests dropped and raised, holds.
  task random_traffic(input integer cycles);
    integer n;
    integer t;
    begin
      for (n = 0; n < cycles; n = n + 1) begin
        rng = xorshift(rng);
        t   = {24'd0, rng[15:8]} % N;
        case (rng[31:30])
          2'd0:    req = rng[N-1:0];
          2'd1:    req = req ^ (ONE_N << t);
          2'd2:    req = req;
          default: req = req | rng[N+1:2];
        endcase
        do_cycle;
      end
    end
  endtask

  initial begin : main
    done              = 1'b0;
    passed            = 32'd0;
    failed            = 32'd0;
    rst_n             = 1'b0;
    req               = NONE;
    ref_ptr           = 0;
    model_valid       = 1'b0;
    exp_win           = -1;
    exp_grant         = NONE;
    max_wait_seen     = 0;
    prev_req          = NONE;
    prev_valid        = 1'b0;
    seen_run          = 1'b0;
    rng               = SEED;
    cov_none          = 0;
    cov_all           = 0;
    cov_maxwait       = 0;
    cov_held          = 0;
    cov_reset_traffic = 0;
    cov_wrap          = 0;
    for (c = 0; c < N; c = c + 1) begin
      wait_cnt[c]  = 0;
      cov_alone[c] = 0;
    end

    // Reset, idle.
    apply(NONE, 3);
    rst_n = 1'b1;
    // No requests.
    apply(NONE, 3);
    // Each requester alone.
    for (c = 0; c < N; c = c + 1) apply(ONE_N << c, 2);
    // Everyone after reset: strict rotation, longest wait N-1, wrap.
    rst_n = 1'b0;
    apply(ALL_N, 2);
    rst_n = 1'b1;
    rotation(3);
    // A held request among changing others, for every requester.
    for (c = 0; c < N; c = c + 1) held(c, 6 * N);
    // Random traffic.
    random_traffic(400);
    // Reset during traffic, with the pointer moved away from 0 first.
    apply(ONE_N << 1, 1);
    rst_n = 1'b0;
    for (c = 0; c < 2; c = c + 1) begin
      rng = xorshift(rng);
      req = rng[N-1:0] | ONE_N;
      do_cycle;
    end
    rst_n = 1'b1;
    rotation(2);
    random_traffic(200);

    // Coverage goals.
    tally(cov_none > 0, 20);
    tally(cov_all > 0, 21);
    tally(cov_maxwait > 0, 22);
    tally(cov_held > 0, 23);
    tally(cov_reset_traffic > 0, 24);
    tally(cov_wrap > 0, 25);
    tally(max_wait_seen <= N - 1, 26);
    for (c = 0; c < N; c = c + 1) tally(cov_alone[c] > 0, 30 + c);

    done = 1'b1;
  end
endmodule

module rr_arbiter_tb;
  localparam integer LIMIT = 100000;

  reg            clk;
  wire           done4;
  wire           done5;
  wire [31:0]    passed4;
  wire [31:0]    failed4;
  wire [31:0]    passed5;
  wire [31:0]    failed5;
  reg  [8*64-1:0] nonce;
  integer        passed;
  integer        failed;
  integer        cyc;

  initial clk = 1'b0;
  always #5 clk = ~clk;

  rr_arbiter_tb_lane #(.N(4), .SEED(32'h1234_5678)) u_lane_n4 (
    .clk    (clk),
    .done   (done4),
    .passed (passed4),
    .failed (failed4)
  );

  rr_arbiter_tb_lane #(.N(5), .SEED(32'h9E37_79B9)) u_lane_n5 (
    .clk    (clk),
    .done   (done5),
    .passed (passed5),
    .failed (failed5)
  );

  initial begin
    nonce = {(8*64){1'b0}};
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) nonce = {(8*64){1'b0}};
    cyc = 0;
    while (((done4 !== 1'b1) || (done5 !== 1'b1)) && (cyc < LIMIT)) begin
      @(posedge clk);
      cyc = cyc + 1;
    end
    #1;
    passed = passed4 + passed5;
    failed = failed4 + failed5;
    if ((done4 !== 1'b1) || (done5 !== 1'b1)) begin
      $error("rr_arbiter_tb: timeout after %0d cycles", cyc);
      failed = failed + 1;
    end
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end
endmodule
=== END FILE ===
